 assert.match(E.PYTHON_RUNTIME_INVENTORY,/import __future__/);assert.match(E.PYTHON_RUNTIME_INVENTORY,/\(10\*\*20000\+1\)\/\/\(10\*\*15000\+3\)/);assert.match(E.PYTHON_RUNTIME_INVENTORY,/scientificDataLoaded.*False/);
