        with localcontext() as c:
            c.prec=90;c.rounding=mode;c.Emin=-999999;c.Emax=999999
            return str(Decimal(v.numerator)/Decimal(v.denominator))
    return box(one(lo,ROUND_FLOOR),one(hi,ROUND_CEILING))

